Lemma art_wf_pkg2 : forall (M' : word -> option byte) ft lt fg lg,
  g_qt FSG Gfr <> [] -> art_batch_list M10 (g_qt FSG Gfr) ft lt -> cellA M10 (0x16a430 + 168) 8 fg -> art_batch_list M10 (g_qg FSG Gfr) fg lg ->
  art_batches_bytes (g_qg FSG Gfr) + art_batches_bytes (g_qt FSG Gfr) <= 2 ^ 28 ->
  mem_grows M10 M' -> art_agree (art_drain_W FSG rn Gfr (Sp - 2208) lg) M10 M' ->
  (cellA M' (rn_t rn + 80) 8 0 /\ cellA M' (rn_t rn + 80 + 8) 8 0 /\ cellA M' (rn_t rn + 80 + 16) 8 0 /\ cellA M' (rn_t rn + 80 + 24) 8 0
   /\ cellA M' (0x16a430 + 160) 8 (Z.of_nat (length (g_qg FSG Gfr)) + Z.of_nat (length (g_qt FSG Gfr))) /\ cellA M' (0x16a430 + 176) 8 lt
   /\ cellA M' (0x16a430 + 184) 8 (art_batches_bytes (g_qg FSG Gfr) + art_batches_bytes (g_qt FSG Gfr)) /\ cellA M' (0x16a430 + 152) 4 0
   /\ (Z.of_nat (length (g_qg FSG Gfr)) = 0 -> cellA M' (0x16a430 + 168) 8 ft) /\ (Z.of_nat (length (g_qg FSG Gfr)) <> 0 -> cellA M' lg 8 ft)) ->
