Section Credit.
Variable FSG : Type.

Lemma art_wfx_credit : forall BUDGET rn (G : art_gs FSG) LB cr u n (kb : nat) k (d : bool),
  let G1 := art_gs_free G (rn_spb rn) k u n kb in
